class Solution {
    public int minSteps(int n) {
        int answer = 0;
        for (int factor = 2; factor * factor <= n; factor++) {
            while (n % factor == 0) {
                answer += factor;
                n /= factor;
            }
        }
        if (n > 1) {
            answer += n;
        }
        return answer;
    }
}

class Solution {
    public int minSteps(int n) {
        return solve(n);
    }

    private int solve(int target) {
        if (target == 1) {
            return 0;
        }
        for (int base = target / 2; base >= 1; base--) {
            if (target % base == 0) {
                return solve(base) + target / base;
            }
        }
        return target;
    }
}

class Solution {
    public int minSteps(int n) {
        int[] dp = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            dp[i] = i;
            for (int d = 2; d * d <= i; d++) {
                if (i % d == 0) {
                    dp[i] = Math.min(dp[i], dp[d] + i / d);
                    dp[i] = Math.min(dp[i], dp[i / d] + d);
                }
            }
        }
        return dp[n];
    }
}

class Solution {
    private int[] memo;

    public int minSteps(int n) {
        memo = new int[n + 1];
        return solve(n);
    }

    private int solve(int target) {
        if (target == 1) {
            return 0;
        }
        if (memo[target] != 0) {
            return memo[target];
        }

        int best = target;
        for (int d = 2; d * d <= target; d++) {
            if (target % d == 0) {
                best = Math.min(best, solve(d) + target / d);
                best = Math.min(best, solve(target / d) + d);
            }
        }
        memo[target] = best;
        return best;
    }
}
